// Oxygen–haemoglobin dissociation curve from the Hill equation: S = P^n / (P50^n + P^n).
const N = 2.7, P50_NORMAL = 26.8, P50_RIGHT = 35, TISSUE = 40;
const X0 = 90, X1 = 590, Y0 = 460, Y1 = 140;           // plot box, PO2 0..100 mmHg, S 0..100 %
const sx = p => X0 + (X1 - X0) * p / 100;
const sy = s => Y0 - (Y0 - Y1) * s;
const sat = (p, p50) => p <= 0 ? 0 : Math.pow(p, N) / (Math.pow(p50, N) + Math.pow(p, N));
function curve(p50) {
  let d = "";
  for (let p = 0; p <= 100; p += 1) d += (p ? " L " : "M ") + sx(p).toFixed(2) + " " + sy(sat(p, p50)).toFixed(2);
  return d;
}
let el = {};
function label(api, text, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700, stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke"}, attrs), api.$("#plot"));
  t.textContent = text; return t;
}
function chip(api, text, x, y) {
  const g = api.el("g", {}, api.$("#plot"));
  api.el("rect", {x: x, y: y - 15, width: 132, height: 30, rx: 15, fill: "#fff1ec", stroke: "#f2b8a6"}, g);
  const t = api.el("text", {x: x + 66, y: y + 1, "text-anchor": "middle", "dominant-baseline": "central", fill: "#b23a1e", "font-size": 15, "font-weight": 700, "font-family": "system-ui,sans-serif"}, g);
  t.textContent = text; return g;
}
function setup(api) {
  const grid = api.$("#grid"), ticks = api.$("#ticks");
  for (let p = 0; p <= 100; p += 20) {
    api.el("line", {x1: sx(p), y1: Y0, x2: sx(p), y2: Y1}, grid);
    const t = api.el("text", {x: sx(p), y: Y0 + 22, "text-anchor": "middle"}, ticks); t.textContent = p;
  }
  for (let s = 0; s <= 1.0001; s += 0.25) {
    api.el("line", {x1: X0, y1: sy(s), x2: X1, y2: sy(s)}, grid);
    const t = api.el("text", {x: X0 - 10, y: sy(s) + 5, "text-anchor": "end"}, ticks); t.textContent = Math.round(s * 100);
  }
  const plot = api.$("#plot");
  el.normal = api.el("path", {d: curve(P50_NORMAL), fill: "none", stroke: "url(#normalStroke)", "stroke-width": 6, "stroke-linecap": "round", pathLength: 1}, plot);
  el.shift = api.el("path", {d: curve(P50_NORMAL), fill: "none", stroke: "url(#shiftStroke)", "stroke-width": 6, "stroke-linecap": "round"}, plot);
  el.p50 = api.el("path", {fill: "none", stroke: "@muted", "stroke-width": 2, "stroke-dasharray": "6 6"}, plot);
  el.p50Label = label(api, "", {x: 0, y: 0, fill: "@muted", "font-size": 15});
  el.tissue = api.el("line", {x1: sx(TISSUE), y1: Y0, x2: sx(TISSUE), y2: Y1, stroke: "@vein", "stroke-width": 3, "stroke-dasharray": "2 7", "stroke-linecap": "round"}, plot);
  el.tissueLabel = label(api, "Tissue PO₂ ≈ 40", {x: sx(TISSUE) + 8, y: Y1 + 18, fill: "@vein", "font-size": 15});
  el.dotN = api.el("circle", {r: 8, fill: "#2a9d8f", stroke: "#fff", "stroke-width": 3}, plot);
  el.dotR = api.el("circle", {r: 8, fill: "#c0392b", stroke: "#fff", "stroke-width": 3}, plot);
  el.gap = api.el("path", {fill: "none", stroke: "@accent", "stroke-width": 5, "stroke-linecap": "round"}, plot);
  el.gapLabel = label(api, "", {x: 584, y: 404, fill: "@accent", "font-size": 16, "text-anchor": "end"});
  el.gapLabel2 = label(api, "→ more O₂ released to tissue", {x: 584, y: 426, fill: "@accent", "font-size": 16, "text-anchor": "end"});
  el.chips = ["↑ CO₂", "↑ H⁺ (↓ pH)", "↑ Temperature", "↑ 2,3-BPG"].map((t, i) => chip(api, t, 452, 250 + i * 38));
  el.normalTag = label(api, "Normal", {x: sx(14), y: sy(0.86), fill: "#1d6f66", "font-size": 17});
  el.rightTag = label(api, "Right shift", {x: sx(50), y: sy(0.66), fill: "#c0392b", "font-size": 17});
}
function show(api, node, t, a, b) {             // fade a node in over [a, b]
  const k = api.seg(t, a, b, "ease_out");
  api.set(node, {opacity: k, display: k > 0 ? "inline" : "none"});
  return k;
}
function render(t, api) {
  // 1. Normal curve draws itself.
  const draw = api.seg(t, 300, 2300, "ease_in_out");
  api.set(el.normal, {"stroke-dasharray": draw.toFixed(4) + " 1.001", "stroke-opacity": draw > 0 ? 1 : 0});
  show(api, el.normalTag, t, 1800, 2400);
  // 2. P50 marker follows the current (shifting) P50.
  const shiftK = api.seg(t, 3600, 6200, "ease_in_out");
  const p50 = P50_NORMAL + (P50_RIGHT - P50_NORMAL) * shiftK;
  api.set(el.p50, {d: "M " + X0 + " " + sy(0.5) + " L " + sx(p50) + " " + sy(0.5) + " L " + sx(p50) + " " + Y0});
  show(api, el.p50, t, 2400, 3000);
  el.p50Label.textContent = "P50 ≈ " + Math.round(p50) + " mmHg";
  api.set(el.p50Label, {x: sx(p50) - 8, y: Y0 - 12, "text-anchor": "end"});
  show(api, el.p50Label, t, 2600, 3200);
  // 3. Right shift: curve recomputed from the Hill equation each frame.
  api.set(el.shift, {d: curve(p50)});
  show(api, el.shift, t, 3500, 3800);
  show(api, el.rightTag, t, 5600, 6200);
  el.chips.forEach((c, i) => {
    const k = show(api, c, t, 3700 + i * 550, 4100 + i * 550);
    api.set(c, {transform: "translate(" + (1 - k) * 24 + " 0)"});
  });
  // 4. At tissue PO2 the right-shifted curve holds less O2, so more is unloaded.
  show(api, el.tissue, t, 6800, 7300); show(api, el.tissueLabel, t, 6900, 7400);
  const sN = sat(TISSUE, P50_NORMAL), sR = sat(TISSUE, p50);
  api.set(el.dotN, {cx: sx(TISSUE), cy: sy(sN)}); show(api, el.dotN, t, 7300, 7700);
  api.set(el.dotR, {cx: sx(TISSUE), cy: sy(sR)}); show(api, el.dotR, t, 7500, 7900);
  const g = api.seg(t, 7900, 8700, "ease_out");
  api.set(el.gap, {d: "M " + (sx(TISSUE) - 6) + " " + sy(sN) + " L " + (sx(TISSUE) - 6) + " " + (sy(sN) + (sy(sR) - sy(sN)) * g)});
  show(api, el.gap, t, 7900, 8000);
  el.gapLabel.textContent = "At PO₂ 40: " + Math.round(sN * 100) + "% → " + Math.round(sR * 100) + "% saturated";
  show(api, el.gapLabel, t, 8500, 9100); show(api, el.gapLabel2, t, 8800, 9400);
}
